ALTER TABLE public.managed_servers ADD COLUMN IF NOT EXISTS synced_at timestamptz;
CREATE UNIQUE INDEX managed_servers_provider_identity ON public.managed_servers(account_id, external_id);
CREATE TABLE public.vmta_pools (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, purpose text NOT NULL DEFAULT 'marketing', status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','paused')), created_by uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.vmta_pools TO authenticated;
GRANT ALL ON public.vmta_pools TO service_role;
ALTER TABLE public.vmta_pools ENABLE ROW LEVEL SECURITY;
CREATE POLICY pools_read ON public.vmta_pools FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'superadmin') OR EXISTS (SELECT 1 FROM public.worker_tasks WHERE user_id=auth.uid() AND status='active' AND allowed_paths && ARRAY['/dashboard/pools','/dashboard/ips','/dashboard/warmup','/dashboard/servers']::text[]));
CREATE TABLE public.server_ips (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), server_id uuid NOT NULL REFERENCES public.managed_servers(id) ON DELETE CASCADE, address text NOT NULL, family integer NOT NULL CHECK(family IN (4,6)), pool_id uuid REFERENCES public.vmta_pools(id) ON DELETE SET NULL, active boolean NOT NULL DEFAULT true, rdns text, synced_at timestamptz NOT NULL DEFAULT now(), UNIQUE(server_id,address));
GRANT SELECT ON public.server_ips TO authenticated;
GRANT ALL ON public.server_ips TO service_role;
ALTER TABLE public.server_ips ENABLE ROW LEVEL SECURITY;
CREATE POLICY ips_read ON public.server_ips FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'superadmin') OR EXISTS (SELECT 1 FROM public.worker_tasks WHERE user_id=auth.uid() AND status='active' AND allowed_paths && ARRAY['/dashboard/pools','/dashboard/ips','/dashboard/warmup','/dashboard/servers']::text[]));
CREATE TABLE public.warmup_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ip_id uuid NOT NULL REFERENCES public.server_ips(id) ON DELETE CASCADE, isp text NOT NULL, daily_limits integer[] NOT NULL, current_day integer NOT NULL DEFAULT 1 CHECK(current_day>=1), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','paused','completed')), created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(ip_id,isp), CHECK(cardinality(daily_limits) BETWEEN 1 AND 90), CHECK(0 < ALL(daily_limits)));
GRANT SELECT ON public.warmup_plans TO authenticated;
GRANT ALL ON public.warmup_plans TO service_role;
ALTER TABLE public.warmup_plans ENABLE ROW LEVEL SECURITY;
CREATE POLICY warmup_read ON public.warmup_plans FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'superadmin') OR EXISTS (SELECT 1 FROM public.worker_tasks WHERE user_id=auth.uid() AND status='active' AND allowed_paths && ARRAY['/dashboard/pools','/dashboard/ips','/dashboard/warmup','/dashboard/servers']::text[]));
CREATE TABLE public.server_domain_bindings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), server_id uuid NOT NULL REFERENCES public.managed_servers(id) ON DELETE CASCADE, domain_id uuid NOT NULL REFERENCES public.sending_domains(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'pending_agent' CHECK(status IN ('pending_agent','installed','error')), installed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(server_id,domain_id));
GRANT SELECT ON public.server_domain_bindings TO authenticated;
GRANT ALL ON public.server_domain_bindings TO service_role;
ALTER TABLE public.server_domain_bindings ENABLE ROW LEVEL SECURITY;
CREATE POLICY bindings_read ON public.server_domain_bindings FOR SELECT TO authenticated USING(public.has_role(auth.uid(), 'superadmin'));
CREATE POLICY workers_servers_read ON public.managed_servers FOR SELECT TO authenticated USING(EXISTS (SELECT 1 FROM public.worker_tasks WHERE user_id=auth.uid() AND status='active' AND allowed_paths && ARRAY['/dashboard/servers','/dashboard/ips','/dashboard/pools','/dashboard/warmup']::text[]));